9	export interface Version {
10	  version: string;
11	  info?: string;
12	  [key: string]: any;
13	}
14	
15	export interface UnknownEntries {
16	  [key: string]: {
17	    [key: string]: any;
18	  };
19	}
20	
21	export interface Versions {
22	  latest?: Version;
23	  next?: Version;
24	  current?: Version;
25	}
26	
27	export interface SubState {
28	  versions: Versions & UnknownEntries;
29	  lastVersionCheck: number;
30	  dismissedVersionNotification: undefined | string;
31	}
32	
33	const checkInterval = 24 * 60 * 60 * 1000;
34	const versionsUrl = 'https://storybook.js.org/versions.json';
35	
36	async function fetchLatestVersion(v: string) {
37	  const fromFetch = await fetch(`${versionsUrl}?current=${v}`);
38	  return fromFetch.json();
39	}
